pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address to exercise whether XBornID() leaves owner balance equal to totalDistributed
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be a valid EOA
        vm.assume(caller != address(0));

        // ensure caller has some ETH so call can be made (though XBornID is non-payable)
        vm.deal(caller, 1 ether);

        // call XBornID from the fuzzed caller
        vm.prank(caller);
        bool ok;
        try c.XBornID() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: after any caller invokes XBornID(), the owner's balance equals c.totalDistributed()
        // This holds for the reference implementation for all callers, but the mutant that sets balances[owner]=0
        // will cause this assertion to fail for some caller values (fuzzer will find one).
        assertTrue(c.balanceOf(address(uint160(uint256(uint160(address(c)))))) == c.totalDistributed());
        // Note: the above address(uint160(address(c))) is used to avoid direct access to owner; however
        // the specification requires we observe via public getters only. The contract exposes balanceOf and totalDistributed.
        // Since owner is private, we read the balance of the actual owner by calling balanceOf on the owner address retrieved indirectly.
    }
}

