pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    // fuzz the caller address to invoke XBornID; the fuzzer will try addresses including the deployer
    function testFuzz_property(address caller) public {
        // avoid zero address (XBornID requires msg.sender == owner to set initial balance)
        vm.assume(caller != address(0));

        // ensure caller has some ETH to call if needed (XBornID is nonpayable but harmless)
        vm.deal(caller, 1 ether);

        // record a key to inspect after call: we will check balances(caller) because it must remain equal to its pre-call value in reference
        uint256 before = c.balanceOf(caller);

        // have caller invoke XBornID()
        vm.prank(caller);
        // call and ignore revert (XBornID requires msg.sender == owner for its assignment; if caller != owner it simply does nothing/reverts). Use try/catch to observe behavior indirectly by checking balance.
        try c.XBornID() {
            // no-op
        } catch {
            // no-op on revert
        }

        uint256 after = c.balanceOf(caller);

        // General fact: in the reference, calling XBornID() never reduces an arbitrary caller's balance below its prior value (the reference only assigns balances[owner] = totalDistributed so other addresses retain their balances); the mutant that sets balances[owner]=0 can cause the deployer's balance to become 0 when owner==caller, but for some fuzzed caller this will reveal a difference in balances for that key.
        // We assert the reference property as: after >= before (balances for the caller do not decrease). This holds for the correct contract for all callers, but the mutant can make balances(owner)=0 which can make after < before for some caller (when caller==owner and owner previously held tokens).
        assertTrue(after >= before);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single test function: supply an arbitrary caller by passing msg.sender-like actor via standard calls
    // We require this contract to be the owner of c so XBornID() will execute; tests should pass an instance whose owner is this contract.
    // The function performs the minimal state-changing call needed and then asserts the distinguishing property.
    function run() public {
        // call the initializer that sets the owner's balance to totalDistributed in the original
        c.XBornID();

        // read owner's address by using transferOwnership/getters are not present for owner, but owner is msg.sender at construction
        // owner is not publicly readable, but the rule can be checked using balanceOf(this)
        // require that this contract is indeed the owner and thus holds the distribution
        // We assert the intended invariant: this contract's balance equals totalDistributed

        uint256 bal = c.balanceOf(address(this));
        uint256 dist = c.totalDistributed();

        assert(bal == dist);
    }

    // allow receiving ether if needed by external tests
    receive() external payable {}
}

