contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // require that caller is the contract owner so XBornID can be called successfully
        // We read the owner indirectly by attempting to call transferOwnership and catching revert is not allowed,
        // instead we require that msg.sender equals c.owner is not possible (owner is not public). So we call XBornID from this contract
        // only callers that are the owner of c can call XBornID; thus the test must be deployed by the same owner.
        // No extra precondition is needed here in the code; leave as true.
        require(true);

        // call the initializer — in original contract this sets owner's balance to totalDistributed;
        // in the mutant it adds totalDistributed to existing balance, so the equality will fail.
        c.XBornID();

        // After initialization, the owner's balance should equal totalDistributed.
        // We cannot read owner directly, but totalDistributed is public and the owner is the deployer (msg.sender at C construction),
        // who must be this contract's caller when this test runs. Since only the owner can successfully call XBornID,
        // we can check that some address's balance equals totalDistributed by iterating not allowed; instead we observe
        // that balanceOf(address(this)) is unrelated. However, the only observable that differs between versions
        // after calling XBornID by the owner is that the owner's balance equals totalDistributed.
        // To refer to the owner, we use that the call succeeded implies msg.sender of C was the owner — i.e. C's owner is address(this).
        // Therefore assert balanceOf(address(this)) == c.totalDistributed().
        assert(c.balanceOf(address(this)) == c.totalDistributed());
    }
    receive() external payable { }
