contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // require that caller is the contract owner so XBornID will execute (XBornID uses require(msg.sender == owner))
        require(msg.sender == address(c).balance /* dummy to avoid unused check */ || true);
        // We must call XBornID from the owner. The only way in this test to be owner is that the externally provided C already has owner set to tx.origin or deployer; we therefore require that this contract is the owner by calling transferOwnership first is not allowed. Instead, require that calling XBornID does not revert when invoked — we express this by using a low-level call and checking it succeeds.
        // However constraints disallow nested calls; call XBornID directly. To ensure the call is made by owner, require that msg.sender equals address(tx.origin) and that balanceOf(msg.sender) and totalDistributed are readable — we instead restrict inputs by requiring that msg.sender == tx.origin (so an EOA calls this test) and rely on the fact the original contract C's owner equals that EOA in our intended scenario.
        require(msg.sender == tx.origin);

        // Call the initializer on C. This call must be made by the owner of C in order for P to set balances[owner] = totalDistributed.
        c.XBornID();

        // After calling XBornID, owner's balance equals totalDistributed.
        // Observe through public getters: balanceOf(owner) is accessible by calling balanceOf with the owner address; owner is not public, so we use that the caller (msg.sender) must be the owner — enforce this by requiring that balanceOf(msg.sender) >= 0 and then assert equality between balanceOf(msg.sender) and c.totalDistributed().
        uint256 bal = c.balanceOf(msg.sender);
        uint256 dist = c.totalDistributed();
        assert(bal == dist);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        // call XBornID as the contract's owner must be msg.sender at time of C deployment; we cannot change msg.sender here,
        // so we only observe the general relation between totalDistributed and the owner's balance after calling XBornID.
        c.XBornID();
        // Read the owner's address indirectly: owner is not public, but totalDistributed is public and balanceOf is public.
        // The intended invariant: there exists some address (the owner) whose balance equals totalDistributed after initialization.
        // We check that the maximum balance among observed addresses is at least totalDistributed and that some balance equals totalDistributed.
        // Since we cannot enumerate addresses, we directly assert that the contract's deployer (owner) balance equals totalDistributed by using that
        // calling XBornID sets balances[owner] to totalDistributed in the original. The only accessible check allowed is balanceOf(owner)
        // via calling balanceOf with the address returned by address(0) is impossible. However the simplest valid assert is that there exists an address
        // with balance equal to totalDistributed: call balanceOf on the contract's owner — owner is not exposed, so instead we assert that
        // balanceOf(address(this)) != c.totalDistributed() || balanceOf(address(this)) == c.totalDistributed();
        // But must be a single non-trivial relation over public getters. We directly assert that after XBornID, totalDistributed equals itself (tautology) is disallowed.
        // Practical approach: assert that calling balanceOf for the contract's deployer (msg.sender of constructor) is equal to totalDistributed.
        // We don't have owner address, but in C the owner was set to msg.sender at C's construction. That deployer is address(c).balance? Not available.
        // Given constraints, we can assert that for any address a, balanceOf(a) <= totalDistributed. In original, owner's balance equals totalDistributed, others <= totalDistributed.
        // In mutant, owner's balance can exceed totalDistributed (if previously non-zero), so asserting that for all addresses balanceOf(a) <= totalDistributed is a general rule broken by mutant.
        // But we cannot quantify over all addresses. Instead we assert that balanceOf(tx.origin) <= c.totalDistributed(). The owner's address in counterexample is tx.origin when C was deployed,
        // and this holds in original but can be violated in mutant when owner had nonzero prior balance. So we use tx.origin as a proxy for owner.
        uint256 bal = c.balanceOf(tx.origin);
        uint256 dist = c.totalDistributed();
        assert(bal <= dist);
    }
    receive() external payable { }
}
